from __future__ import annotations


class Group:
    def __init__(self, members: list[str]) -> None:
        self._members = list(members)
        self._member_set = set(self._members)
        self._balances: dict[str, float] = {member: 0.0 for member in self._members}

    def add_expense(
        self,
        payer: str,
        amount: float,
        participants: list[str] | None = None,
    ) -> None:
        """Record that `payer` paid `amount` on behalf of `participants`."""
        if amount <= 0:
            raise ValueError("Expense amount must be strictly positive.")

        if payer not in self._member_set:
            raise ValueError(f"Payer '{payer}' is not a group member.")

        if participants is None:
            involved = self._members
        else:
            if not participants:
                raise ValueError("Participants list cannot be empty.")
            for p in participants:
                if p not in self._member_set:
                    raise ValueError(f"Participant '{p}' is not a group member.")
            involved = participants

        # Payer is credited the full amount
        self._balances[payer] += amount

        # Each participant owes an equal split
        split_share = amount / len(involved)
        for p in involved:
            self._balances[p] -= split_share

    def balances(self) -> dict[str, float]:
        """Net balance per member. Positive = the member is owed money,
        negative = the member owes money."""
        return dict(self._balances)

    def settle_up(self) -> list[tuple[str, str, float]]:
        """Payments that settle the group, as (debtor, creditor, amount)."""
        # Collect creditors (positive balance) and debtors (negative balance)
        debtors: list[list[str | float]] = []
        creditors: list[list[str | float]] = []

        for member in self._members:
            bal = self._balances[member]
            if bal < 0:
                debtors.append([member, -bal])
            elif bal > 0:
                creditors.append([member, bal])

        payments: list[tuple[str, str, float]] = []
        i, j = 0, 0

        # Greedy matching produces at most (number of members - 1) transactions
        while i < len(debtors) and j < len(creditors):
            debtor, debt_amount = debtors[i][0], float(debtors[i][1])
            creditor, cred_amount = creditors[j][0], float(creditors[j][1])

            settle_amount = min(debt_amount, cred_amount)

            # Ignore amounts below 1.00 (written off)
            if settle_amount >= 1.00:
                payments.append((debtor, creditor, round(settle_amount, 2)))

            debtors[i][1] = debt_amount - settle_amount
            creditors[j][1] = cred_amount - settle_amount

            # Move to the next debtor/creditor once fully settled (or epsilon left)
            if debtors[i][1] < 1e-9:
                i += 1
            if creditors[j][1] < 1e-9:
                j += 1

        return payments
```

